EPD=' through our Lord Jesus Christ, Your Son, who lives and reigns with You in the unity of the Holy Spirit, God, world without end.'
def it(after,pre,la,en,src,en_src='dm',**kw):
    d={"after":after,"chant":True,"pre":pre,"la":la,"en":en,"src":src,"en_src":en_src}; d.update(kw); return d
INTER_SATSEPT=[
 it(0,'Orémus.','Da nobis, quǽsumus omnípotens Deus: ut jejunándo tua grátia satiémur; et abstinéndo cunctis efficiámur hóstibus fortióres:'+CONC,
    'Grant us, almighty God, we beseech You, that by our fasting we may be filled with Your grace, and by abstinence be made stronger than all our foes:'+EPD,'M39 p. 292 (pdf 185L)',
    rubric='Post Kýrie eléison, quinque sequentes Oratiónes dicántur sine Dóminus vobíscum, sed dicátur: Orémus (p. 291).'),
 it(1,'Orémus.','Tuere, quǽsumus Dómine, famíliam tuam: ut salútis ætérnæ remédia, quæ te inspiránte requírimus; te largiénte consequámur:'+CONC,
    'Guard Your fold, we beseech You, O Lord, that the blessings of eternal salvation, which by Your prompting we seek, we may by Your bounty obtain:'+EPD,'M39 p. 292 (pdf 185L)'),
 it(2,'Orémus.','Præsta, quǽsumus Dómine, sic nos ab épulis abstinére carnálibus; ut a vítiis irruéntibus páriter jejunémus:'+CONC,
    'Grant us, almighty God, we pray, so to abstain from food, that we may likewise fast from the vices that attack us:'+EPD,'M39 p. 292 (pdf 185L)'),
 it(3,'Orémus.','Ut nobis, Dómine, tríbuis solémne tibi deférre jejúnium; sic nobis, quǽsumus, indulgéntiæ præsta subsídium:'+CONC,
    'Even as You grant us to offer this solemn fast, O Lord, we pray You bestow the aid of Your pardon:'+EPD,'M39 p. 293 (pdf 185R)'),
 it(4,'Dóminus vobíscum. Orémus.','Deus, qui tribus púeris mitigásti flammas ígnium; concéde propítius, ut nos fámulos tuos non exúrat flamma vitiórum:'+CONC,
    'O God, who tempered the flames of fire for the three young men, mercifully grant that we Your servants may not be consumed by the flames of vice:'+EPD,'M39 p. 294 (pdf 186L)',
    rubric='Postea dicatur: Dóminus vobíscum (after the Hymn). Secunda Oratio A cunctis, p. 287, vel sequens Concéde (nos fámulos tuos … lætítia), juxta Rubricas. Tertia Oratio ad libitum (p. 294).'),
]
